import SwiftUI
import SwiftData

@Model
final class TodoItem {
  @Attribute(.unique) var id: UUID = UUID()
  var title: String
  var done: Bool
  var createdAt: Date = Date()
  init(title: String, done: Bool = false) { self.title = title; self.done = done }
}

// SwiftUI integration
@main
struct MyApp: App {
  var body: some Scene {
    WindowGroup { TodoListView() }
      .modelContainer(for: TodoItem.self)
  }
}

struct TodoListView: View {
  @Environment(\.modelContext) private var ctx
  @Query(sort: \TodoItem.createdAt, order: .reverse) private var items: [TodoItem]

  var body: some View {
    List {
      ForEach(items) { item in
        Toggle(isOn: Binding(get: { item.done }, set: { item.done = $0 })) {
          Text(item.title)
        }
      }
      .onDelete { indexes in
        for i in indexes { ctx.delete(items[i]) }
      }
    }
    .toolbar {
      Button("Add") {
        ctx.insert(TodoItem(title: "New"))
      }
    }
  }
}

// Migrations — declare schemas + use VersionedSchema for non-trivial changes
// CloudKit sync — pass `cloudKitDatabase: .private("iCloud.example")` to ModelConfiguration

import Security
import Foundation

enum Keychain {
  static func save(_ value: Data, account: String) throws {
    let query: [String: Any] = [
      kSecClass as String: kSecClassGenericPassword,
      kSecAttrAccount as String: account,
      kSecValueData as String: value,
      kSecAttrAccessible as String: kSecAttrAccessibleAfterFirstUnlockThisDeviceOnly,
    ]
    SecItemDelete(query as CFDictionary) // remove existing if any
    let status = SecItemAdd(query as CFDictionary, nil)
    guard status == errSecSuccess else { throw KeychainError(status: status) }
  }

  static func read(account: String) -> Data? {
    let query: [String: Any] = [
      kSecClass as String: kSecClassGenericPassword,
      kSecAttrAccount as String: account,
      kSecReturnData as String: true,
      kSecMatchLimit as String: kSecMatchLimitOne,
    ]
    var item: CFTypeRef?
    let status = SecItemCopyMatching(query as CFDictionary, &item)
    return status == errSecSuccess ? item as? Data : nil
  }

  static func delete(account: String) {
    let query: [String: Any] = [
      kSecClass as String: kSecClassGenericPassword,
      kSecAttrAccount as String: account,
    ]
    SecItemDelete(query as CFDictionary)
  }
  struct KeychainError: Error { let status: OSStatus }
}

// Usage
try Keychain.save(Data("jwt".utf8), account: "access_token")
